  "dbdump.toggle": "每次备份前转储数据库",
  "dbdump.toggleHint": "BombVault 已把这个容器识别为 {engine} 数据库。每次备份前，它会向运行中的服务器要一份完整的 SQL 转储，并作为独立的还原点直接存进备份仓库，不会往你的磁盘写任何文件。还原使用容器停止后拍下的文件备份；转储是第二份副本，你可以下载或导入。转储失败绝不会让备份失败，它会显示为一次独立的失败运行。",
  "dbdump.toggleHintLabel": "容器标签 bombvault.dbdump 为这个 {engine} 数据库开启了转储。每次备份前，BombVault 会向运行中的服务器要一份完整的 SQL 转储，并作为独立的还原点存下。转储失败绝不会让备份失败，它会显示为一次独立的失败运行。",
  "dbdump.toggleHintOnlyCopy": "每次备份前，BombVault 会向这台运行中的 {engine} 服务器要一份完整的 SQL 转储，并作为独立的还原点存下。对这个容器来说，转储是数据库唯一一致的副本：它的数据目录要么在服务器运行时被复制，要么根本不在任何备份里。请让转储保持开启。转储失败绝不会让备份失败，它会显示为一次独立的失败运行。",
  "dbdump.toggleHintUnknown": "每次备份前，BombVault 会向这台运行中的 {engine} 服务器要一份完整的 SQL 转储，并作为独立的还原点存下。无法确定这个容器把数据目录放在哪里，所以不知道文件备份里是否有可用的副本。转储才是你能指望的副本。请保持开启。转储失败绝不会让备份失败，它会显示为一次独立的失败运行。",
  "dbdump.lookalikeHint": "这个容器看着像 {engine} 数据库，但 BombVault 并不确定它的镜像。如果确实是，就开启转储；如果随后失败，说明该镜像没有遵循常见设置，你可以再关掉。",
