  "dbdump.globalOff": "自动数据库转储已在设置的常规里对所有容器关闭。",
  "dbdump.offConfirmLive": "要关闭这个数据库的转储吗？它的数据目录是在服务器运行时复制的，没有转储就不存在一致的副本。",
  "dbdump.offConfirmNone": "要关闭这个数据库的转储吗？它的数据目录不在任何备份里，没有转储就什么也留不下。",
  "dbdump.offConfirmUnknown": "要关闭这个数据库的转储吗？BombVault 无法确定它的数据目录在哪里，所以不知道是否有哪份备份含有可用的副本。",
  "dbdump.coverageStopped": "数据目录：在容器停止时保存。",
  "dbdump.coverageLive": "数据目录：在服务器运行时复制。一致的副本是转储。",
  "dbdump.coverageNone": "数据目录：不在任何备份里。唯一的副本是转储。",
  "dbdump.coverageUnknown": "数据目录：无法确定。请让转储保持开启。",
  "dbdump.coverageHint": "数据库一直在写自己的文件。只有在拍摄期间服务器处于停止状态，这些文件的副本才可靠，而 BombVault 对容器备份里的目录正是这么做的。compose 项目或目录集合中的目录是在服务器运行时复制的，appdata 之外的目录则根本不复制。在这些情况下，你要还原的就是转储。",
