  "dbdump.updateWarnSameMajor": "这是一个数据库。镜像更新可能把它带到新的主版本。MySQL 和 MariaDB 只能把转储导入它所来自的主版本，所以如果新版本拒绝旧的数据目录，请把镜像退回上一个版本，再在那里导入更新前刚拍下的转储。",
  "dbdump.stackRestoreWarn": "{names} 的数据是在整套服务运行时复制的。还原之后，请先导入它们最新的数据库转储，再使用这些应用。",
  "dbdump.introNotice": "BombVault 会在每次备份前转储它识别出的数据库，作为各自独立的还原点。这里识别出 {n} 个，第一个是 {name}。你可以在容器卡片上逐个关闭，或在设置里对所有容器关闭。",
  "dbdump.introDismiss": "知道了",
  "dbdump.fixAuth": "请检查数据库容器自身的密码变量（例如 POSTGRES_PASSWORD、MARIADB_ROOT_PASSWORD 或 MYSQL_ROOT_PASSWORD，或它们的 _FILE 版本）。转储用的正是这些。",
  "dbdump.fixPrivileges": "转储只能以应用用户身份登录，而该用户缺少它需要的权限。请给容器一个真正的 root 密码，而不是随机密码。",
  "dbdump.fixUnreachable": "数据库服务器没有在本地套接字上应答。看看容器日志，它可能还在启动或已经崩溃。",
  "dbdump.fixNotRunning": "备份运行时容器处于暂停或正在重启。如果它一直重启，请查看它的日志。",
  "dbdump.fixNoClient": "镜像里没有转储工具。请使用官方镜像，或关闭这个容器的转储。",
  "dbdump.fixSecret": "容器用户读不到 _FILE 变量里指定的密码文件。请检查路径及其权限。",
  "dbdump.fixNoCredentials": "容器设置里既没有 root 密码，也没有带数据库的用户。请设置 MARIADB_ROOT_PASSWORD（或 MYSQL_ROOT_PASSWORD），或者一个用户和一个数据库。",
  "dbdump.fixNeedsUpgrade": "数据库的系统表来自较早的版本。请给容器加上变量 MARIADB_AUTO_UPGRADE，值为 1，然后重启；或者在容器里执行一次 mariadb-upgrade。",
  "dbdump.fixTimeout": "转储达到了时间上限。数据库非常大时，请给 BombVault 容器加上变量 DB_DUMP_MAX_HOURS（Unraid：编辑容器，Add another Path, Port, Variable），例如 12。",
  "dbdump.fixBackupCap": "转储还在进行时，整次备份已达到 BACKUP_MAX_HOURS。请调高 BombVault 容器上的 BACKUP_MAX_HOURS。",
  "dbdump.fixStalled": "转储停止推进，通常是因为应用持有锁。下一次备份会再试一次。",
  "dbdump.fixDumpData": "转储工具带着所示消息停了下来。下一次备份会再试；如果一直失败，那条消息会说明原因。",
  "dbdump.fixDocker": "Docker 没有执行转储命令。通常是备份启动时容器被停止、暂停或重建。下一次备份会再试；如果反复发生，请检查 Docker 服务以及 BombVault 对它的访问。",
  "dbdump.fixRepository": "备份仓库没有接收这份转储，或者存下的字节数少于转出的。请在设置的“目标”里检查仓库；下一次备份会再试。",
  "dbdump.fixLeftover": "损坏的转储无法从仓库中移除。请在备份面板的转储列表里删除它。",
  "dbdump.fixHelper": "BombVault 的转储助手结束时没有给出结果。如果反复出现，请提交问题并附上诊断包。",
  "dbdump.listTitle": "数据库转储",
  "dbdump.listHint": "每份转储都是在备份前从运行中的数据库取得的完整 SQL 导出。BombVault 绝不会自行把转储写回去：恢复容器会恢复它的文件，如果这些文件是在容器停止时保存的，那它们才是更新的副本。当这些文件不可用时才使用转储：它们在服务器运行时被复制、根本没有被复制、数据库换到了新的主版本，或者数据目录损坏。导入会把转储放进一个刚启动的空数据库，并把旧的数据目录留在旁边。完整的 .sql 文件以一行 \"complete\" 注释结束。",
