  "dbdump.import": "导入到新的数据库",
  "dbdump.importConfirm": "把这份 {engine} {version} 转储导入 {container} 吗？BombVault 会停止容器，把它的数据目录挪到一边（保留，不删除任何东西），用空的数据目录启动容器，然后导入转储。使用该数据库的应用之后看到的是转储时刻的状态。",
  "dbdump.importConfirmNoVersion": "把这份 {engine} 转储导入 {container} 吗？BombVault 会停止容器，把它的数据目录挪到一边（保留，不删除任何东西），用空的数据目录启动容器，然后导入转储。使用该数据库的应用之后看到的是转储时刻的状态。",
