  "mcp.title": "MCP 服务器",
  "mcp.hint": "让 Claude 这类 AI 助手通过 Model Context Protocol 读取本服务器的备份状态、启动备份，并取消它们自己启动的备份。恢复、删除和设置仍留在这个网页界面里。",
