  "mcp.setupFile": "把这段加到配置文件里，放在已有的服务器旁边。",
  "mcp.setupFileUi": "在 {app} 中，{ui} 会打开这个文件。",
  "mcp.setupPaste": "也可以在 {app} 的 {ui} 中直接粘贴。",
  "mcp.setupForm": "在 {app} 的 {ui} 中填写这些值。",
  "mcp.setupOther": "任何会说 Streamable HTTP 的客户端都可以。在它要求填写远程 MCP 服务器的地方填入这些内容，密钥放在两个头中的任意一个。",
  "mcp.setupWhere": "文件位置",
  "mcp.setupNeedsNode": "需要 Node.js，因为 mcp-remote 负责把 {app} 连接到 BombVault。",
  "mcp.keyFileLine": "把密钥以 X-API-Key: <key> 这一行保存到文本文件中，并把该文件的路径填进配置。{app} 只保存路径，所以密钥既不会出现在配置里，也不会出现在进程列表中。",
  "mcp.keyFileJsonTip": "在这个 JSON 文件里，路径请用正斜杠书写，例如 C:/Users/sam/bombvault-key.txt，因为单个反斜杠不是有效的 JSON。密钥文件的路径不要包含空格：在 Windows 上，{app} 会把带空格的路径拆成两段传给 npx。",
  "mcp.keyEnv": "{app} 从环境变量 {var} 读取密钥。",
  "mcp.keyEnvTip": "把它设置为用户环境变量，只需一次：Windows 在 设置、系统、关于、高级系统设置、环境变量 中；macOS 和 Linux 在你的 shell 配置文件中。然后重新启动 {app}。如果在命令行用 setx 或 export 输入，密钥会留在 shell 历史中。在 macOS 上从 Dock 或 Finder 启动的应用不会读取 shell 配置文件：只把密钥放进一个文件，例如 ~/.bombvault-key，在终端中运行 launchctl setenv {var} \"$(cat ~/.bombvault-key)\"，然后重新打开 {app}，每次重启 Mac 后都要再做一次。",
  "mcp.keyEnvUnsure": "如果 {app} 发送的是变量名而不是密钥，就把密钥直接写进文件中的相应位置，并且只让你自己保管这个文件。",
  "mcp.keyPrompt": "{app} 在第一次启动服务器时询问密钥，并把它保存在自己的机密存储中，所以文件里没有密钥。",
  "mcp.keyDotenv": "{app} 从 {file} 中的 {var}=<key> 这一行读取密钥。这个文件只让你自己保管。",
  "mcp.keyInFile": "{app} 无法从别处读取密钥，所以密钥以明文形式放在这个文件里。只让你自己保管这个文件，不要放进共享文件夹或版本控制。",
  "mcp.keyInApp": "{app} 把密钥保存在自己的设置中，据其文档所述并未加密。任何能打开这些设置的人都能读到它。",
  "mcp.keyCredential": "{app} 把密钥加密保存在自己的凭据中：用它创建一个 Bearer Auth 类型的凭据，并在节点中选择它。工作流只记录凭据的名称。",
  "mcp.keyVendor": "{app} 把密钥保存在其提供商的服务器上，并在每次调用时发送。",
  "mcp.keyOther": "如果客户端能从环境变量、机密输入提示或系统钥匙串读取密钥，就用这种方式，而不要把密钥写进它的设置。",
  "mcp.certPlaceholder": "BombVault 使用自己的证书。配置已让 Node.js 指向它：下载文件，并用它的路径替换证书占位符。",
  "mcp.certEnv": "BombVault 使用自己的证书。如果 {app} 拒绝它，请把环境变量 {var} 设为下载文件的路径，然后重新启动 {app}。",
  "mcp.certEnvTip": "在你设置用户环境变量的地方设置它：Windows 在 设置、系统、关于、高级系统设置、环境变量 中；macOS 和 Linux 在你的 shell 配置文件中；容器则在其设置中，并把文件挂载进去。每当 BombVault 签发新证书时，都要重新下载。在 macOS 上从 Dock 或 Finder 启动的应用不会读取 shell 配置文件：对这类应用，请在终端中带上文件路径运行 launchctl setenv {var}，然后重新打开应用，每次重启 Mac 后都要再做一次。",
  "mcp.certSystem": "BombVault 使用自己的证书。如果 {app} 拒绝它，请把下载的文件添加到系统的受信任证书中，然后重新启动 {app}。",
  "mcp.certSystemTip": "在 Windows 上，把文件重命名为 bombvault-cert.crt，打开它并依次选择 安装证书、当前用户、将所有的证书都放入下列存储、受信任的根证书颁发机构。也可以带上文件路径运行 certutil -user -addstore Root。在 macOS 上，用钥匙串访问把它加入登录钥匙串，并设为始终信任。在 Linux 上，以 .crt 扩展名复制到 /usr/local/share/ca-certificates，然后运行 update-ca-certificates。",
  "mcp.certOwnList": "BombVault 使用自己的证书，而 {app} 按照自己的证书列表检查证书，这个列表无法添加内容。如果它拒绝 BombVault 的证书，请通过带有公开受信任证书的反向代理访问 BombVault。",
  "mcp.certOther": "BombVault 使用自己的证书。让客户端指向下载的文件，或把它添加到系统的受信任证书中。",
  "mcp.certOtherTip": "基于 Node.js 的客户端从 NODE_EXTRA_CA_CERTS 读取文件。大多数其他客户端使用系统信任的证书。绝不要关闭证书检查。",
  "mcp.waitTitle": "正在等待第一次调用",
  "mcp.connectedTitle": "已连接",
